BEGIN READ ONLY; SET LOCAL statement_timeout='10s';
SELECT jsonb_build_object('captured_at',clock_timestamp(),'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_arguments(p.oid),'return',pg_get_function_result(p.oid),'acl',p.proacl,'config',p.proconfig,'md5',md5(p.prosrc)) ORDER BY p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('apply_import_session','begin_account_deletion','check_concierge_rate_limit','curated_rail_cards','delete_account_club_memberships','delete_user_concierge_data','get_concierge_config','is_flag_enabled','llm_budget_finalize','llm_budget_reserve','llm_global_budget_finalize','llm_global_budget_reserve','log_concierge_run','rag_retrieve_candidates','recommend_ids_premium','recommend_ids_similar_to_seeds','search_titles','undo_import_session')),'relations',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity) ORDER BY c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('account_deletion_barriers','anime','club_members','concierge_mode_cache','editorial_boosts','editorial_tag_boosts','episodes','feature_flags','manga','profiles','rag_retrieval_cache','tags','title_aliases','user_lists'))) AS runtime_dependencies; ROLLBACK;
